package com.jmadsen.dashhop;
import android.content.*;import android.media.session.MediaController;import android.graphics.*;import android.graphics.drawable.*;import android.media.*;import android.media.session.*;import android.os.*;import android.view.*;import android.widget.*;
final class AudioPanel extends LinearLayout implements AudioSessionRepository.Listener {
 final AudioSessionRepository audio;final ShortcutRepository repo;final TextView source,title,detail,status,position;final ImageView art;final LinearLayout controls,expanded;final TextView openSaved;final Handler h=new Handler(Looper.getMainLooper());long mask=-1;TextView toggle;boolean attached,large;String lastSession="";
 AudioPanel(Context c){super(c);repo=new ShortcutRepository(c);audio=AudioSessionRepository.get(c);setOrientation(VERTICAL);setPadding(8,8,8,8);ScrollView sc=new ScrollView(c);LinearLayout content=new LinearLayout(c);content.setOrientation(VERTICAL);sc.addView(content);addView(sc,new LayoutParams(-1,-1));source=text("Audio Mini",19);title=text("",22);detail=text("",16);status=text("",14);position=text("",14);art=new ImageView(c);art.setScaleType(ImageView.ScaleType.CENTER_INSIDE);LinearLayout summary=new LinearLayout(c);summary.addView(art,new LayoutParams(UtilityPopupManager.px(80),UtilityPopupManager.px(80)));LinearLayout words=new LinearLayout(c);words.setOrientation(VERTICAL);words.addView(source);words.addView(title);words.addView(detail);summary.addView(words,new LayoutParams(0,-2,1));content.addView(summary);content.addView(status);openSaved=button("Open Last Played app",audio::openSaved);content.addView(openSaved);controls=new LinearLayout(c);content.addView(controls);expanded=new LinearLayout(c);expanded.setOrientation(VERTICAL);expanded.addView(position);content.addView(expanded);content.addView(button("Compact / expanded",()->{large=!large;expanded.setVisibility(large?VISIBLE:GONE);changed();}));expanded.setVisibility(GONE);content.addView(button("LAUNCH RADIO",this::radio));content.addView(button("Audio setup / notification access",()->AppLaunchManager.settings(c,"audio")));}
 TextView text(String value,int size){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(4,4,4,4);return t;}
 TextView button(String s,Runnable run){TextView t=text(s,16);t.setGravity(Gravity.CENTER);t.setMinHeight(UtilityPopupManager.px(48));t.setOnClickListener(v->run.run());return t;}
 void command(String name){AudioFocusCoordinator.get(getContext()).userCommand();audio.command(name);}
 void control(String text,String command){controls.addView(button(text,()->command(command)),new LayoutParams(0,UtilityPopupManager.px(52),1));}
 public void changed(){boolean shown=audio.displayable();source.setText(shown?audio.displaySource():"Audio Mini");title.setText(shown?(audio.displayTitle().isEmpty()?"Metadata unavailable":audio.displayTitle()):AudioSessionRepository.EMPTY);detail.setText(shown?audio.displayDetail():"");boolean savedOnly=!audio.has()&&audio.remembered();boolean available=savedOnly&&audio.canOpenSaved();String savedStatus=available?"Last Played · saved information. Open the app to resume; playback is not guaranteed.":"Last Played · app unavailable. Choose another installed source.";status.setText(savedOnly?savedStatus+(audio.notice.isEmpty()?"":"\n"+audio.notice):!audio.notice.isEmpty()?audio.notice:audio.has()?audio.stateLabel()+(audio.network().isEmpty()?"":" · "+audio.network()):"Start playback in an installed compatible app.");openSaved.setVisibility(savedOnly?VISIBLE:GONE);openSaved.setEnabled(available);openSaved.setText(available?"Open Last Played app":"Last Played app unavailable");Bitmap artwork=audio.displayArtwork();art.setImageBitmap(artwork);if(artwork!=null&&repo.flag("audioWallpaper",true)){BitmapDrawable bg=new BitmapDrawable(getResources(),artwork);bg.setGravity(Gravity.FILL);bg.setColorFilter(0xff404c55,PorterDuff.Mode.MULTIPLY);setBackground(bg);}else setBackgroundColor(0xff14384b);
 long actions=audio.actions();if(!lastSession.equals(audio.selected)||mask!=actions){lastSession=audio.selected;while(expanded.getChildCount()>1)expanded.removeViewAt(1);}if(mask!=actions){mask=actions;controls.removeAllViews();if(audio.supports(PlaybackState.ACTION_SKIP_TO_PREVIOUS))control("Previous","previous");if(audio.supports(PlaybackState.ACTION_REWIND))control("Rewind","rewind");if(audio.supports(PlaybackState.ACTION_PLAY)||audio.supports(PlaybackState.ACTION_PAUSE)||audio.supports(PlaybackState.ACTION_PLAY_PAUSE)){toggle=button("",()->command(audio.playing()?(audio.supports(PlaybackState.ACTION_PAUSE)?"pause":"toggle"):(audio.supports(PlaybackState.ACTION_PLAY)?"play":"toggle")));controls.addView(toggle,new LayoutParams(0,UtilityPopupManager.px(52),1));}else toggle=null;if(audio.supports(PlaybackState.ACTION_FAST_FORWARD))control("Forward","forward");if(audio.supports(PlaybackState.ACTION_SKIP_TO_NEXT))control("Next","next");}
 if(toggle!=null){boolean supported=audio.playing()?(audio.supports(PlaybackState.ACTION_PAUSE)||audio.supports(PlaybackState.ACTION_PLAY_PAUSE)):(audio.supports(PlaybackState.ACTION_PLAY)||audio.supports(PlaybackState.ACTION_PLAY_PAUSE));toggle.setEnabled(supported);toggle.setText(audio.playing()?"Pause":"Play");}updatePosition();}
 void updatePosition(){MediaController m=audio.controller;PlaybackState s=audio.playback;if(!large||m==null||s==null){position.setText("");while(expanded.getChildCount()>1)expanded.removeViewAt(1);return;}long pos=s.getPosition();boolean known=pos>=0;if(known&&audio.playing())pos+=Math.max(0,SystemClock.elapsedRealtime()-s.getLastPositionUpdateTime())*s.getPlaybackSpeed();MediaMetadata data=m.getMetadata();long duration=data==null?0:data.getLong(MediaMetadata.METADATA_KEY_DURATION);if(duration>0)pos=Math.min(duration,pos);position.setText((known?time(pos):"Position unavailable")+(known&&duration>0?" / "+time(duration):"")+"\n"+(audio.network().isEmpty()?"":audio.network()));if(expanded.getChildCount()==1){if(known&&audio.supports(PlaybackState.ACTION_SEEK_TO)&&duration>0){SeekBar seek=new SeekBar(getContext());seek.setMax(1000);seek.setProgress((int)Math.min(1000,Math.max(0,pos*1000/duration)));seek.setContentDescription("Seek within current content");seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){if(audio.controller==m&&audio.supports(PlaybackState.ACTION_SEEK_TO)){AudioFocusCoordinator.get(getContext()).userCommand();try{m.getTransportControls().seekTo(duration*b.getProgress()/1000);}catch(RuntimeException e){Diagnostics.error("media_seek_failed",e);}}}});expanded.addView(seek);}MediaController.PlaybackInfo info=m.getPlaybackInfo();if(info!=null&&info.getVolumeControl()!=VolumeProvider.VOLUME_CONTROL_FIXED){TextView volume=button("Volume − / + (selected session)",()->{});expanded.addView(volume);LinearLayout row=new LinearLayout(getContext());row.addView(button("−",()->volume(-1)),new LayoutParams(0,-2,1));row.addView(button("+",()->volume(1)),new LayoutParams(0,-2,1));expanded.addView(row);}}}
 void volume(int direction){try{if(audio.controller!=null)audio.controller.adjustVolume(direction,AudioManager.FLAG_SHOW_UI);}catch(RuntimeException e){Diagnostics.error("media_volume_failed",e);}}
 static String time(long millis){long sec=Math.max(0,millis/1000);return String.format(java.util.Locale.getDefault(),"%d:%02d",sec/60,sec%60);}
 void radio(){String id=repo.str("radioApp","");if(id.isEmpty()){Toast.makeText(getContext(),"Choose a Radio target in Audio Mini Settings",Toast.LENGTH_LONG).show();AppLaunchManager.settings(getContext(),"audio");return;}AppLaunchManager.launch(getContext(),id);}
 final Runnable tick=new Runnable(){public void run(){if(attached){try{updatePosition();}catch(RuntimeException e){position.setText("Session unavailable");}h.postDelayed(this,1000);}}};
 protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;audio.acquire();audio.add(this);changed();h.post(tick);}
 protected void onDetachedFromWindow(){attached=false;h.removeCallbacksAndMessages(null);audio.remove(this);audio.release();super.onDetachedFromWindow();}
}
